<?php require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/widgets.php';require_once __DIR__.'/../includes/calendar_view.php';$u=require_role('medico');$m=row('SELECT * FROM medicos WHERE usuario_id=?',[$u['id']]);$today=all('SELECT c.*,u.nombre,u.apellido_paterno FROM citas c JOIN pacientes p ON p.id=c.paciente_id JOIN usuarios u ON u.id=p.usuario_id WHERE c.medico_id=? AND c.fecha=CURDATE() ORDER BY c.hora',[$m['id']]);$annual=row('SELECT COUNT(*) n FROM citas WHERE medico_id=? AND YEAR(fecha)=YEAR(CURDATE()) AND estado="atendida"',[$m['id']]);header_ui('¡Buen día, Dr(a). '.$u['nombre'].'!');?><section class="welcome-banner"><div><span class="pill pill-light">✦ TU CONSULTORIO DIGITAL</span><h2>Una consulta a la vez, una vida mejor.</h2><p>Organiza tu jornada y mantén el seguimiento de tus pacientes.</p><a class="btn btn-white" href="<?=url('medico/agenda.php')?>">Revisar agenda →</a></div><div class="banner-heart">✚</div></section><div class="stat-grid"><?php stat_card('🗓','Consultas de hoy',count($today));stat_card('♥','Pacientes atendidos este año',$annual['n']??0,'lavender');stat_card('✓','Verificación',$m['verificado']?'Aprobada':'Pendiente','peach');?></div><?php $visits=(int)($annual['n']??0);$milestones=[10,50,100,250,500];$reached=0;foreach($milestones as $goal){if($visits>=$goal)$reached=$goal;}if($reached): ?><section class="doctor-incentive"><span>🏅 RECONOCIMIENTO DIGITAL · <?=date('Y')?></span><strong>¡Felicidades, Dr(a). <?=e($u['nombre'])?>!</strong><p>Has atendido <?=number_format($visits)?> consultas en este año y alcanzaste la meta de <?=$reached?> pacientes. Gracias por tu compromiso con la salud.</p><a class="btn btn-ghost btn-sm" href="<?=url('medico/reconocimiento.php')?>">Ver felicitación digital</a></section><?php endif;?><?php if(!$m['especialidad_id']):?><div class="alert alert-info">Para aparecer en las búsquedas de pacientes, <a href="<?=url('medico/perfil.php')?>"><strong>elige tu especialidad en Mi perfil</strong></a>. Después solicita verificación al administrador y configura tus horarios.</div><?php elseif(!all('SELECT id FROM horarios_medicos WHERE medico_id=? LIMIT 1',[$m['id']])):?><div class="alert alert-info">Tu especialidad está registrada. <a href="<?=url('medico/agenda.php')?>"><strong>Agrega horarios de atención</strong></a> para que los pacientes puedan seleccionar una fecha.</div><?php endif;?><?php calendar_view('medico'); ?><div class="panel"><div class="panel-heading"><h2>Agenda de hoy</h2><a href="<?=url('medico/agenda.php')?>">Ver agenda →</a></div><?php if(!$today):empty_state('Sin citas para hoy','Puedes gestionar tus horarios y consultar tu agenda.');else:foreach($today as $c):?><div class="appointment-row"><div class="date-square"><strong><?=ui_time($c['hora'])?></strong></div><div class="appointment-info"><strong><?=e($c['nombre'].' '.$c['apellido_paterno'])?></strong><small><?=e(ucfirst($c['estado']))?></small></div><span class="badge badge-mint"><?=e($c['estado'])?></span></div><?php endforeach;endif;?></div><?php if(!$m['verificado']):?><div class="alert alert-info">Tu perfil todavía no está verificado. Completa tu especialidad y solicita la revisión de tus documentos con el administrador.</div><?php endif;?><?php footer_ui();?>
